    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    # Split into components
    components = path.split('/')

    # Start with root
    current = '/'
    link_count = 0

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            continue

        # Append component
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if it's a symlink
        while candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                target_components = target.split('/')
            else:
                # Relative target - relative to directory containing the link
                if candidate == '/':
                    link_dir = '/'
                else:
                    link_dir = candidate.rsplit('/', 1)[0]
                    if not link_dir:
                        link_dir = '/'

                current = link_dir
                target_components = target.split('/')

            # Process target components
            for tc in target_components:
                if tc == '' or tc == '.':
                    continue

                if tc == '..':
                    if current != '/':
                        current = current.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    continue

                # Append target component
                if current == '/':
                    current = '/' + tc
                else:
                    current = current + '/' + tc

                # Check again if this is a symlink
                if current in links:
                    break
            else:
                # All target components processed, no early break
                candidate = current
                break

            # Early break occurred, loop back to check the new candidate
            candidate = current
        else:
            # Not a symlink
            current = candidate

    # Return result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current.rstrip('/')

